// "Save for offline": a button and side panel that keep a copy of the whole
// course in the browser, so it runs without internet. The service worker
// (sw.js, generated by build/offline.mjs) serves that copy when offline.
//
// Saving has two steps:
//   1. every file in offline-manifest.json goes into the browser's cache;
//   2. R packages (dplyr) are installed once, so the service worker keeps the
//      files webR downloads for them.
//
// What's been saved is remembered in localStorage, so the panel can say
// "saved" or "the course has changed since you saved".

import { esc } from "./markdown.js";

const KEY = "rcourse:v1:offline";
const mb = (n) => (n / 1e6).toFixed(0) + " MB";

function remembered() {
  try { return JSON.parse(localStorage.getItem(KEY)) ?? null; } catch { return null; }
}
function remember(v) {
  try { localStorage.setItem(KEY, JSON.stringify(v)); } catch { /* storage full or blocked */ }
}

/** Register the service worker. Safe to call on every page. */
export async function register() {
  if (!("serviceWorker" in navigator)) return null;
  try { return await navigator.serviceWorker.register("./sw.js"); }
  catch (e) { console.warn("offline copy unavailable:", e); return null; }
}

async function getManifest() {
  const res = await fetch("./offline-manifest.json", { cache: "no-store" });
  if (!res.ok) throw new Error("offline-manifest.json is missing — run `npm run build`");
  return res.json();
}

/**
 * Save every file in the manifest. `onProgress(done, total)` is called in
 * bytes as files arrive. Files already in the right cache are skipped, so
 * saving again after a small change is quick.
 */
async function saveFiles(m, onProgress) {
  const already = new Set();
  for (const f of m.files) {
    if (await caches.match(new URL(f.path, location.href).href, { cacheName: m.caches[f.cache] })) {
      already.add(f.path);
    }
  }
  let done = m.files.filter((f) => already.has(f.path)).reduce((n, f) => n + f.bytes, 0);
  onProgress(done, m.bytes);
  const open = {};
  // A few at a time: quick, without swamping a slow connection.
  const queue = m.files.filter((f) => !already.has(f.path));
  async function worker() {
    while (queue.length) {
      const f = queue.shift();
      const cache = open[f.cache] ??= await caches.open(m.caches[f.cache]);
      const res = await fetch(f.path, { cache: "no-store" });
      if (!res.ok) throw new Error(`couldn't save ${f.path} (${res.status})`);
      await cache.put(new URL(f.path, location.href).href, res);
      done += f.bytes;
      onProgress(done, m.bytes);
    }
  }
  await Promise.all([worker(), worker(), worker(), worker()]);
}

/**
 * Install each package once in a short-lived copy of R. webR downloads the
 * package files itself; the service worker keeps every one it fetches.
 * Returns the packages that couldn't be saved.
 */
async function savePackages(packages, onStatus) {
  if (!packages.length) return [];
  const { WebR } = await import("./vendor/webr/webr.mjs");
  const w = new WebR({ baseUrl: new URL("./vendor/webr/", import.meta.url).href });
  const failed = [];
  try {
    onStatus("starting R to save its packages…");
    await w.init();
    for (const p of packages) {
      onStatus(`saving the ${p} package…`);
      try {
        await w.installPackages([p], { quiet: true });
        const ok = await (await w.evalR(`requireNamespace("${p}", quietly = TRUE)`)).toBoolean();
        if (!ok) failed.push(p);
      } catch { failed.push(p); }
    }
  } finally {
    try { w.close(); } catch { /* already closed */ }
  }
  return failed;
}

/* ------------------------------------------------------------------ panel --- */

let panel, body, btn;

function statusHtml(m, saved) {
  if (!saved) {
    return `<p><strong>Not saved yet.</strong> This course runs in your browser, but it needs
      the internet to load. Save it once, and it works without a connection.</p>`;
  }
  const when = new Date(saved.at).toLocaleDateString(undefined, { day: "numeric", month: "long", year: "numeric" });
  const pkgs = saved.packagesFailed?.length
    ? `<p class="offwarn">The ${saved.packagesFailed.map(esc).join(", ")} package couldn't be saved, so
        modules that use it will still need the internet. Try saving again while you're online.</p>` : "";
  if (m && saved.version !== m.version) {
    return `<p><strong>Saved on ${when}, but the course has changed since.</strong> Save again to
      get the latest version. Your progress is kept either way.</p>${pkgs}`;
  }
  return `<p><strong>Saved on ${when}.</strong> The whole course, including R, works without
    internet in this browser.</p>${pkgs}`;
}

async function render() {
  let m = null;
  try { m = await getManifest(); } catch { /* offline, and nothing saved */ }
  const saved = remembered();
  const size = m ? mb(m.bytes) : "about 46 MB";
  body.innerHTML = `
    <div class="offstatus">${statusHtml(m, saved)}</div>
    <p class="offrow">
      <button class="act" id="offsave" ${m ? "" : "disabled"}>
        ${saved ? "Save again" : "Save the course for offline use"}</button>
      <span class="offsize">${esc(size)}</span>
    </p>
    <div class="offprogress" hidden><div class="offbar"><div class="offfill"></div></div>
      <p class="offmsg" aria-live="polite"></p></div>
    <h3>What works offline</h3>
    <p>Everything except the grading of written answers, which needs an AI on our server.
      Offline, those show the criteria and an example answer instead, so you can check your
      own and carry on.</p>
    <h3>Keeping it saved</h3>
    <p>Browsers can clear saved sites to free space. Safari is the strictest: it removes a
      site's saved copy — and your progress — if you don't open it for about a week. Adding
      the course to your Home Screen (iPhone, iPad) or Dock (Mac) should keep it.</p>
    ${saved ? `<p><button class="linky" id="offremove">Remove the offline copy</button>
      <span class="offsize">frees about ${esc(size)}; your progress is kept</span></p>` : ""}`;
  body.querySelector("#offsave")?.addEventListener("click", () => save(m));
  body.querySelector("#offremove")?.addEventListener("click", removeCopy);
}

async function save(m) {
  const go = body.querySelector("#offsave");
  const prog = body.querySelector(".offprogress");
  const fill = body.querySelector(".offfill");
  const msg = body.querySelector(".offmsg");
  go.disabled = true;
  prog.hidden = false;
  const say = (t) => { msg.textContent = t; };
  try {
    if (!(await register())) throw new Error("this browser can't keep an offline copy");
    await navigator.serviceWorker.ready;
    // Ask the browser to treat the saved copy as worth keeping.
    try { await navigator.storage?.persist?.(); } catch { /* not supported */ }
    await saveFiles(m, (done, total) => {
      const pct = Math.floor((done / total) * 100);
      fill.style.width = pct + "%";
      say(`Saving the course… ${pct}% (${mb(done)} of ${mb(total)})`);
    });
    const failed = navigator.onLine ? await savePackages(m.packages ?? [], say) : m.packages ?? [];
    remember({ version: m.version, at: Date.now(), bytes: m.bytes, packagesFailed: failed });
    say(failed.length ? "Saved, except one package — see above." : "Saved. The course now works without internet.");
  } catch (e) {
    say(`Couldn't finish saving: ${e.message ?? e}. Check your connection and try again — anything already saved is kept.`);
  }
  go.disabled = false;
  const keepMsg = msg.textContent;
  await render();
  body.querySelector(".offprogress").hidden = false;
  body.querySelector(".offfill").style.width = "100%";
  body.querySelector(".offmsg").textContent = keepMsg;
}

async function removeCopy() {
  for (const k of await caches.keys()) if (k.startsWith("rcourse-")) await caches.delete(k);
  try { localStorage.removeItem(KEY); } catch { /* blocked */ }
  await render();
}

function open() {
  document.dispatchEvent(new CustomEvent("sidepanel:open", { detail: "offline" }));
  panel.hidden = false;
  requestAnimationFrame(() => panel.classList.add("open"));
  render();
}
function close() {
  panel.classList.remove("open");
  setTimeout(() => { panel.hidden = true; }, 180);
}

/** Put the "Save for offline" button in `host`, and register the service worker. */
export function mount(host) {
  register();
  if (!host || !("caches" in window)) return;
  btn = document.createElement("button");
  btn.className = "linky";
  btn.id = "offbtn";
  btn.textContent = "Save for offline";
  btn.onclick = () => (panel.hidden ? open() : close());
  host.append(btn);

  panel = document.createElement("aside");
  panel.className = "sidepanel";
  panel.id = "offpanel";
  panel.hidden = true;
  panel.setAttribute("aria-label", "Save for offline");
  panel.innerHTML = `
    <div class="panelhead"><header><h2>Save for offline</h2>
      <button class="linky offclose" aria-label="Close">Close</button></header>
      <p class="fncount">Use the course without an internet connection.</p></div>
    <div class="panelbody offbody"></div>`;
  panel.querySelector(".offclose").onclick = close;
  document.body.append(panel);
  body = panel.querySelector(".offbody");
  document.addEventListener("sidepanel:open", (e) => { if (e.detail !== "offline" && !panel.hidden) close(); });
}
